def find_regions(grid):
    visited = set()
    regions = []

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != 0 and (r, c) not in visited:
                region = []
                size = 0
                stack = [(r, c)]

                while stack:
                    cr, cc = stack.pop()
                    if (cr, cc) in visited or grid[cr][cc] != grid[r][c]:
                        continue
                    visited.add((cr, cc))
                    size += 1
                    region.append((cr, cc))
                    for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                            if grid[nr][nc] == grid[r][c] and (nr, nc) not in visited:
                                stack.append((nr, nc))

                if size < 3:
                    continue

                bbox_r = sorted([x[0] for x in region])
                bbox_c = sorted([x[1] for x in region])
                center_r = sorted(bbox_r)[len(bbox_r)//2]
                center_c = sorted(bbox_c)[len(bbox_c)//2]

                regions.append({
                    'value': grid[r][c],
                    'center': (center_r, center_c)
                })

    return regions

def transform(grid):
    rows = len(grid)
    cols = len(grid[0])

    regions = find_regions(grid)

    fill_rows = {}
    fill_cols = {}

    for reg in regions:
        center_r, center_c = reg['center']
        val = reg['value']
        fill_rows[center_r] = val
        fill_cols[center_c] = val

    fill_source = {}  # (r,c) -> [(val, 'row'), (val, 'col')]

    for r, val in fill_rows.items():
        for c in range(cols):
            if (r, c) not in fill_source:
                fill_source[(r, c)] = []
            fill_source[(r, c)].append((val, 'r'))

    for c, val in fill_cols.items():
        for r in range(rows):
            if (r, c) not in fill_source:
                fill_source[(r, c)] = []
            fill_source[(r, c)].append((val, 'c'))

    final_cells = {}
    for (r, c), factors in fill_source.items():
        if not factors:
            continue

        row_val = None
        col_val = None
        row_fill_count = 0
        col_fill_count = 0

        for val, factor in factors:
            if factor == 'r':
                row_val = val
                row_fill_count += 1
            elif factor == 'c':
                col_val = val
                col_fill_count += 1

        if row_fill_count + col_fill_count == 1:
            final_value = row_val if row_fill_count == 1 else col_val
        elif row_fill_count > 0 and col_fill_count > 0:
            if row_val == col_val:
                final_value = row_val
            else:
                final_value = 0
        else:
            continue

        final_cells[(r, c)] = final_value

    result = [[0] * cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0 and (r, c) not in fill_source:
                result[r][c] = grid[r][c]

    for (r, c), final_val in final_cells.items():
        result[r][c] = final_val

    return result

